# ZCode Voice Input - one-click installer
# Supports ZCode 3.16.2 (Windows x64). Installs a local whisper.cpp microphone button.
[CmdletBinding()]
param(
    [string]$ZCodePath = '',
    [string]$PackageDir = '',
    [string]$ModelPath = '',
    [string]$WhisperZipPath = '',
    [string]$AsarPath = '',
    [switch]$Uninstall,
    [switch]$DryRun,
    [switch]$NoLaunch,
    [switch]$ForceClose,
    [switch]$UseSystemNode,
    [switch]$KeepWork
)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'

$script:AppName = 'ZCode'
$script:SupportedVersion = '3.16.2'
$script:ModelSha = 'ae85e4a935d7a567bd102fe55afc16bb595bdb618e11b2fc7591bc08120411bb'
$script:WhisperZipSha = '0d2eca299c248f965bd0341bcb219db4b433c7f0c0ce2200d4df85765e8156a9'
$script:WhisperUrl = 'https://github.com/ggml-org/whisper.cpp/releases/download/v1.7.6/whisper-bin-x64.zip'
$script:ModelUrls = @(
    'https://huggingface.co/ggerganov/whisper.cpp/resolve/main/ggml-small-q5_1.bin',
    'https://hf-mirror.com/ggerganov/whisper.cpp/resolve/main/ggml-small-q5_1.bin'
)
$script:EngineHashes = @{
    'whisper-cli.exe' = 'b7c6dc2e999a80bc2d23cd4c76701211f392ae55d5cabdf0d45eb2ca4faf09af'
    'whisper.dll' = 'bbeceed370799687a363244edc583bac3dc5d472f5bd14691a26f22c7e710bb8'
    'ggml.dll' = 'f91ef57cfd6d2f07a5fc33e5dca114b3dc3abe8495f47b46dfbe178d6d775c37'
    'ggml-base.dll' = 'e912e19071c32d673a81de4aab058d36328cc6b0c59c75889a0ba4c65fd6a4e6'
    'ggml-cpu.dll' = '341ed96e2520ef9b44509f18b5ac4f60d171e47a6c55ab390d704ea7b06ae617'
}
$script:WorkerSha = 'c6977a0d87177ea2829037c4b7b28f92c7624e612e66f1f9d338d8d80d996666'
$script:Root = Join-Path $env:LOCALAPPDATA 'ZCodeVoice'
$script:Cache = Join-Path $script:Root 'cache'
$script:BackupDir = Join-Path $script:Root 'backup'
$script:LogDir = Join-Path $script:Root 'logs'
$script:StateFile = Join-Path $script:Root 'state.json'
$script:LogFile = Join-Path $script:LogDir 'install.log'
$script:Work = $null
$script:ZCode = $null
$script:AsarBackup = $null
$script:AsarReplaced = $false
$script:Utf8NoBom = New-Object System.Text.UTF8Encoding($false)

try {
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
} catch {
    # older systems already default to a usable protocol
}

# Embedded payloads (base64 keeps the exact verified bytes). Everything runs locally.
$script:VoiceEntryB64 = ''
$script:VoiceUiB64 = ''
$script:PreloadPatchB64 = ''
$script:AsarPatchB64 = ''
$script:VoiceWorkerB64 = ''

$script:NoticeText = @'
# Voice input third-party notices

- whisper.cpp v1.7.6 (Windows x64 prebuilt, MIT): https://github.com/ggml-org/whisper.cpp
  - bundled binary set: whisper-cli.exe, whisper.dll, ggml.dll, ggml-base.dll, ggml-cpu.dll
- Whisper small model, ggml-small-q5_1.bin (OpenAI Whisper weights, MIT; ggml conversion by whisper.cpp):
  https://huggingface.co/ggerganov/whisper.cpp
  - SHA-256: AE85E4A935D7A567BD102FE55AFC16BB595BDB618E11B2FC7591BC08120411BB
- voice-worker.mjs: local integration script, no network access.

All inference runs locally. Audio is written only to a per-request temp file and deleted immediately after transcription.
'@

function Write-Log {
    param([string]$Message, [string]$Level = 'INFO')
    try {
        $line = '{0} [{1}] {2}' -f (Get-Date).ToString('yyyy-MM-dd HH:mm:ss'), $Level, $Message
        [IO.File]::AppendAllText($script:LogFile, $line + [Environment]::NewLine, $script:Utf8NoBom)
    } catch {
        # logging must never break installation
    }
}
function Write-Step { param([string]$Message) Write-Host "`n==> $Message" -ForegroundColor Cyan; Write-Log $Message }
function Write-Info { param([string]$Message) Write-Host "    $Message"; Write-Log $Message }
function Write-Ok { param([string]$Message) Write-Host "    $Message" -ForegroundColor Green; Write-Log $Message }
function Write-Warn { param([string]$Message) Write-Host "    $Message" -ForegroundColor Yellow; Write-Log $Message 'WARN' }
function Write-Err { param([string]$Message) Write-Host "`n[错误] $Message" -ForegroundColor Red; Write-Log $Message 'ERROR' }
function Fail { param([string]$Message) throw $Message }

function Get-Sha256 {
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path)) { return '' }
    return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()
}
function Assert-Hash {
    param([string]$Path, [string]$Expected, [string]$Label)
    $actual = Get-Sha256 $Path
    if ($actual -ne $Expected.ToLowerInvariant()) {
        Fail "$Label 校验失败：$actual（期望 $Expected）"
    }
}
function Format-Mb {
    param([long]$Bytes)
    return ('{0:N0} MB' -f ($Bytes / 1MB))
}
function Assert-FreeSpace {
    param([string]$Path, [long]$NeedBytes)
    try {
        $full = [IO.Path]::GetFullPath($Path)
        $root = [IO.Path]::GetPathRoot($full)
        $drive = New-Object IO.DriveInfo($root)
        if ($drive.AvailableFreeSpace -lt $NeedBytes) {
            Fail "磁盘空间不足：$root 只剩 $(Format-Mb $drive.AvailableFreeSpace)，至少需要 $(Format-Mb $NeedBytes)。"
        }
    } catch {
        # if the drive cannot be inspected, let the actual write fail with a normal error
    }
}

function Initialize-Dirs {
    New-Item -ItemType Directory -Force -Path $script:Root, $script:Cache, $script:BackupDir, $script:LogDir | Out-Null
}

function Show-Banner {
    Write-Host ''
    Write-Host '  ZCode 本地语音输入 - 一键安装' -ForegroundColor White
    Write-Host '  ZCode 3.16.2 / Windows x64 / 完全离线' -ForegroundColor DarkGray
    Write-Host ''
    Write-Log 'installer started'
}

function Resolve-ZCode {
    param([string]$Override)
    $candidates = New-Object System.Collections.Generic.List[string]
    if ($Override) {
        if (Test-Path -LiteralPath $Override -PathType Leaf) {
            $candidates.Add((Split-Path -Parent ([IO.Path]::GetFullPath($Override))))
        } elseif (Test-Path -LiteralPath $Override -PathType Container) {
            $candidates.Add(([IO.Path]::GetFullPath($Override)))
        } else {
            Fail "指定的 ZCodePath 不存在：$Override"
        }
    }

    Get-Process ZCode -ErrorAction SilentlyContinue | ForEach-Object {
        if ($_.Path) { $candidates.Add((Split-Path -Parent $_.Path)) }
    }
    if ($env:LOCALAPPDATA) { $candidates.Add((Join-Path $env:LOCALAPPDATA 'Programs\ZCode')) }
    if ($env:ProgramFiles) { $candidates.Add((Join-Path $env:ProgramFiles 'ZCode')) }
    if (${env:ProgramFiles(x86)}) { $candidates.Add((Join-Path ${env:ProgramFiles(x86)} 'ZCode')) }

    $hives = @(
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall',
        'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall',
        'HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'
    )
    foreach ($hive in $hives) {
        if (-not (Test-Path $hive)) { continue }
        Get-ChildItem $hive -ErrorAction SilentlyContinue | ForEach-Object {
            $entry = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue
            if (-not $entry -or $entry.DisplayName -notlike 'ZCode*') { return }
            if ($entry.InstallLocation -and (Test-Path -LiteralPath $entry.InstallLocation)) {
                $candidates.Add($entry.InstallLocation)
            }
            if ($entry.DisplayIcon) {
                $icon = ($entry.DisplayIcon -replace '^"', '') -replace '",?.*$', ''
                if (Test-Path -LiteralPath $icon) { $candidates.Add((Split-Path -Parent $icon)) }
            }
            if ($entry.UninstallString) {
                $m = [regex]::Match($entry.UninstallString, '^\s*"([^"]+\.exe)"|^\s*(\S+\.exe)')
                if ($m.Success) {
                    $exe = if ($m.Groups[1].Success) { $m.Groups[1].Value } else { $m.Groups[2].Value }
                    if (Test-Path -LiteralPath $exe) { $candidates.Add((Split-Path -Parent $exe)) }
                }
            }
        }
    }

    foreach ($dir in ($candidates | Select-Object -Unique)) {
        $exe = Join-Path $dir 'ZCode.exe'
        $asar = Join-Path $dir 'resources\app.asar'
        if ((Test-Path -LiteralPath $exe) -and (Test-Path -LiteralPath $asar)) {
            return [pscustomobject]@{
                Dir = $dir
                Exe = $exe
                Asar = $asar
                Version = (Get-Item -LiteralPath $exe).VersionInfo.ProductVersion
            }
        }
    }
    Fail "找不到 ZCode 安装。请先安装 ZCode 3.16.2，或用 -ZCodePath 指定安装目录。"
}

function Assert-SupportedVersion {
    param($ZCode)
    if (-not $ZCode.Version -or $ZCode.Version -notlike "$($script:SupportedVersion)*") {
        Fail "当前 ZCode 版本是 $($ZCode.Version)，本脚本只支持 $($script:SupportedVersion)（Windows x64）。"
    }
}

function Get-TargetProcesses {
    param($ZCode)
    if (-not $ZCode) { return @() }
    $target = [IO.Path]::GetFullPath($ZCode.Exe)
    return @(Get-Process ZCode -ErrorAction SilentlyContinue | Where-Object {
        $path = $_.Path
        if (-not $path) { return $false }
        return ([IO.Path]::GetFullPath($path) -eq $target)
    })
}

function Close-ZCodeForInstall {
    param($ZCode)
    $procs = @(Get-TargetProcesses $ZCode)
    if ($procs.Count -eq 0) { return }
    Write-Warn 'ZCode 正在运行，安装前需要关闭。'
    if (-not $ForceClose) {
        for ($i = 5; $i -gt 0; $i--) {
            Write-Host "    $i 秒后自动关闭 ZCode（按 Ctrl+C 取消）..." -ForegroundColor Yellow
            Start-Sleep -Seconds 1
        }
    }
    foreach ($p in $procs) {
        try {
            if ($p.MainWindowHandle -ne 0) { $null = $p.CloseMainWindow() }
        } catch {
            # helper processes have no window
        }
    }
    $deadline = (Get-Date).AddSeconds(15)
    while ((Get-Date) -lt $deadline) {
        if (@(Get-TargetProcesses $ZCode).Count -eq 0) { return }
        Start-Sleep -Milliseconds 400
    }
    Write-Warn 'ZCode 未正常退出，强制结束进程。'
    @(Get-TargetProcesses $ZCode) | Stop-Process -Force -ErrorAction SilentlyContinue
    Start-Sleep -Seconds 1
    if (@(Get-TargetProcesses $ZCode).Count -gt 0) { Fail '无法关闭 ZCode，请手动退出后重试。' }
}

function Start-ZCodeApp {
    param($ZCode)
    if ($NoLaunch) { Write-Info '已跳过启动 ZCode（-NoLaunch）。'; return }
    Write-Step '启动 ZCode'
    Start-Process -FilePath $ZCode.Exe -WorkingDirectory $ZCode.Dir
    Start-Sleep -Seconds 3
    if (@(Get-TargetProcesses $ZCode).Count -gt 0) {
        Write-Ok 'ZCode 已启动。点击输入框右侧麦克风即可使用。'
    } else {
        Write-Warn 'ZCode 启动命令已发出，但未检测到进程；请手动启动。'
    }
}

function Invoke-CapturedProcess {
    param([string]$Exe, [string[]]$Arguments, [bool]$ElectronNode)
    $outFile = Join-Path $script:Work ('stdout-' + [guid]::NewGuid().ToString('N') + '.log')
    $errFile = Join-Path $script:Work ('stderr-' + [guid]::NewGuid().ToString('N') + '.log')
    $quoted = ($Arguments | ForEach-Object {
        if ($_ -match '[\s"]') { '"' + ($_ -replace '"', '\"') + '"' } else { $_ }
    }) -join ' '
    $old = $env:ELECTRON_RUN_AS_NODE
    $oldNoAsar = $env:ELECTRON_NO_ASAR
    if ($ElectronNode) {
        $env:ELECTRON_RUN_AS_NODE = '1'
        # Electron's Node mode otherwise treats any *.asar path as an archive.
        $env:ELECTRON_NO_ASAR = '1'
    }
    try {
        $proc = Start-Process -FilePath $Exe -ArgumentList $quoted -Wait -PassThru -NoNewWindow `
            -RedirectStandardOutput $outFile -RedirectStandardError $errFile
        $output = @()
        if (Test-Path -LiteralPath $outFile) { $output += @(Get-Content -LiteralPath $outFile -Encoding UTF8) }
        if (Test-Path -LiteralPath $errFile) { $output += @(Get-Content -LiteralPath $errFile -Encoding UTF8) }
        return [pscustomobject]@{ ExitCode = $proc.ExitCode; Output = $output }
    } finally {
        if ($ElectronNode) {
            if ($null -eq $old) { Remove-Item Env:\ELECTRON_RUN_AS_NODE -ErrorAction SilentlyContinue }
            else { $env:ELECTRON_RUN_AS_NODE = $old }
            if ($null -eq $oldNoAsar) { Remove-Item Env:\ELECTRON_NO_ASAR -ErrorAction SilentlyContinue }
            else { $env:ELECTRON_NO_ASAR = $oldNoAsar }
        }
        Remove-Item -LiteralPath $outFile, $errFile -Force -ErrorAction SilentlyContinue
    }
}

function Invoke-Node {
    param([string]$ScriptPath, [string[]]$NodeArgs)
    $attempts = @()
    if (-not $UseSystemNode) {
        $attempts += @{ Kind = 'zcode'; Exe = $script:ZCode.Exe }
    }
    $systemNode = Get-Command node -ErrorAction SilentlyContinue
    if ($systemNode) { $attempts += @{ Kind = 'system'; Exe = $systemNode.Source } }
    if ($attempts.Count -eq 0) { Fail '没有可用的 Node 运行时。' }

    $last = ''
    $allArgs = @($ScriptPath) + $NodeArgs
    foreach ($attempt in $attempts) {
        try {
            $result = Invoke-CapturedProcess -Exe $attempt.Exe -Arguments $allArgs -ElectronNode ($attempt.Kind -eq 'zcode')
            $code = $result.ExitCode
            $output = @($result.Output)
        } catch {
            $code = -1
            $output = @($_.Exception.Message)
        }
        if ($code -eq 0) { return $output }
        $last = ($output | Out-String).Trim()
        Write-Log "node attempt failed ($($attempt.Kind), exit $code): $last" 'WARN'
        Write-Warn "Node 执行失败（$($attempt.Kind)，exit $code），尝试下一种方式。"
    }
    Fail "补丁器执行失败：`n$last"
}

function Get-AsarInfo {
    param([string]$Path)
    $patcher = Join-Path $script:Work 'asar-patch.mjs'
    $output = Invoke-Node -ScriptPath $patcher -NodeArgs @('--check', '--asar', $Path)
    $jsonLine = $output | Where-Object { $_ -match '^\s*\{' } | Select-Object -Last 1
    if (-not $jsonLine) { Fail '无法读取 app.asar 信息。' }
    return ($jsonLine | ConvertFrom-Json)
}

function Get-Asset {
    param(
        [string]$Label,
        [string]$Destination,
        [string]$ExpectedSha,
        [string[]]$Urls,
        [string]$LocalPath
    )
    if (Test-Path -LiteralPath $Destination) {
        if ((Get-Sha256 $Destination) -eq $ExpectedSha.ToLowerInvariant()) {
            Write-Ok "使用已缓存的 $Label"
            return $Destination
        }
        Remove-Item -LiteralPath $Destination -Force
    }

    if ($LocalPath) {
        if (-not (Test-Path -LiteralPath $LocalPath)) { Fail "本地文件不存在：$LocalPath" }
        Copy-Item -LiteralPath $LocalPath -Destination $Destination -Force
        Assert-Hash $Destination $ExpectedSha $Label
        Write-Ok "已使用本地 $Label"
        return $Destination
    }

    $lastError = ''
    foreach ($url in $Urls) {
        $tmp = "$Destination.part"
        try {
            if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Force }
            Write-Step "下载 $Label（$url）"
            Write-Info '首次安装需要下载，之后会使用本地缓存。'
            $bits = Get-Command Start-BitsTransfer -ErrorAction SilentlyContinue
            $downloaded = $false
            if ($bits) {
                try {
                    Start-BitsTransfer -Source $url -Destination $tmp -Priority Foreground -ErrorAction Stop
                    $downloaded = $true
                } catch {
                    Write-Warn "BITS 下载失败，改用 HTTP 下载：$($_.Exception.Message)"
                }
            }
            if (-not $downloaded) {
                Invoke-WebRequest -Uri $url -OutFile $tmp -UseBasicParsing -Headers @{ 'User-Agent' = 'Mozilla/5.0' }
            }
            Assert-Hash $tmp $ExpectedSha $Label
            Move-Item -LiteralPath $tmp -Destination $Destination -Force
            Write-Ok "下载完成，SHA-256 校验通过。"
            return $Destination
        } catch {
            $lastError = $_.Exception.Message
            Write-Warn "这个地址不可用：$lastError"
            if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue }
        }
    }
    Fail "下载 $Label 失败。最后错误：$lastError`n可以手动下载，或用 -PackageDir / -ModelPath / -WhisperZipPath 指定本地文件。"
}

function Test-VoiceRuntime {
    param([string]$VoiceDir)
    if (-not (Test-Path -LiteralPath $VoiceDir)) { return $false }
    if ((Get-Sha256 (Join-Path $VoiceDir 'ggml-small-q5_1.bin')) -ne $script:ModelSha) { return $false }
    if ((Get-Sha256 (Join-Path $VoiceDir 'voice-worker.mjs')) -ne $script:WorkerSha) { return $false }
    foreach ($name in $script:EngineHashes.Keys) {
        if ((Get-Sha256 (Join-Path $VoiceDir "whisper\Release\$name")) -ne $script:EngineHashes[$name]) { return $false }
    }
    return $true
}

function Install-VoiceRuntime {
    param([string]$VoiceDir, [string]$WhisperZip, [string]$ModelFile)
    if (Test-VoiceRuntime $VoiceDir) {
        Write-Ok "语音资源已存在：$VoiceDir"
        return $VoiceDir
    }
    Write-Step '安装语音资源'
    $whisperDir = Join-Path $VoiceDir 'whisper\Release'
    New-Item -ItemType Directory -Force -Path $whisperDir | Out-Null
    $extract = Join-Path $script:Work 'whisper-extract'
    if (Test-Path -LiteralPath $extract) { Remove-Item -LiteralPath $extract -Recurse -Force }
    Expand-Archive -LiteralPath $WhisperZip -DestinationPath $extract -Force
    $cli = Get-ChildItem -LiteralPath $extract -Recurse -Filter 'whisper-cli.exe' -File | Select-Object -First 1
    if (-not $cli) { Fail 'whisper 压缩包里找不到 whisper-cli.exe。' }
    $releaseDir = $cli.Directory.FullName
    foreach ($name in $script:EngineHashes.Keys) {
        $src = Join-Path $releaseDir $name
        if (-not (Test-Path -LiteralPath $src)) { Fail "whisper 压缩包缺少 $name。" }
        Copy-Item -LiteralPath $src -Destination (Join-Path $whisperDir $name) -Force
        Assert-Hash (Join-Path $whisperDir $name) $script:EngineHashes[$name] $name
    }
    Copy-Item -LiteralPath $ModelFile -Destination (Join-Path $VoiceDir 'ggml-small-q5_1.bin') -Force
    Assert-Hash (Join-Path $VoiceDir 'ggml-small-q5_1.bin') $script:ModelSha '模型'
    [IO.File]::WriteAllBytes((Join-Path $VoiceDir 'voice-worker.mjs'), [Convert]::FromBase64String($script:VoiceWorkerB64))
    Assert-Hash (Join-Path $VoiceDir 'voice-worker.mjs') $script:WorkerSha 'voice-worker.mjs'
    [IO.File]::WriteAllText((Join-Path $VoiceDir 'NOTICE.md'), $script:NoticeText, $script:Utf8NoBom)
    $manifest = [ordered]@{
        voice_version = 1
        engine = 'whisper.cpp v1.7.6'
        model = 'ggml-small-q5_1.bin'
        model_sha256 = $script:ModelSha
        installed_at = (Get-Date).ToString('o')
    }
    [IO.File]::WriteAllText((Join-Path $VoiceDir 'manifest.json'), ($manifest | ConvertTo-Json), $script:Utf8NoBom)
    Write-Ok "语音资源安装完成：$VoiceDir"
    return $VoiceDir
}

function Get-Assets {
    param([string]$BaseDir)
    $modelLocal = $ModelPath
    $whisperLocal = $WhisperZipPath
    if ($PackageDir) {
        if (-not $modelLocal) { $modelLocal = Join-Path $PackageDir 'ggml-small-q5_1.bin' }
        if (-not $whisperLocal) { $whisperLocal = Join-Path $PackageDir 'whisper-bin-x64.zip' }
    }
    $modelFile = Join-Path $script:Cache 'ggml-small-q5_1.bin'
    $whisperZip = Join-Path $script:Cache 'whisper-bin-x64.zip'
    Get-Asset -Label 'whisper.cpp 引擎（约 3.5 MB）' -Destination $whisperZip -ExpectedSha $script:WhisperZipSha -Urls @($script:WhisperUrl) -LocalPath $whisperLocal | Out-Null
    Get-Asset -Label 'Whisper small 模型（约 181 MB）' -Destination $modelFile -ExpectedSha $script:ModelSha -Urls $script:ModelUrls -LocalPath $modelLocal | Out-Null
    return @{ Model = $modelFile; WhisperZip = $whisperZip }
}

function Write-EmbeddedFiles {
    param([string]$Dir)
    New-Item -ItemType Directory -Force -Path $Dir | Out-Null
    [IO.File]::WriteAllBytes((Join-Path $Dir 'voice-entry.js'), [Convert]::FromBase64String($script:VoiceEntryB64))
    [IO.File]::WriteAllBytes((Join-Path $Dir 'voice-ui.js'), [Convert]::FromBase64String($script:VoiceUiB64))
    [IO.File]::WriteAllBytes((Join-Path $Dir 'preload-patch.cjs'), [Convert]::FromBase64String($script:PreloadPatchB64))
    [IO.File]::WriteAllBytes((Join-Path $Dir 'asar-patch.mjs'), [Convert]::FromBase64String($script:AsarPatchB64))
}

function Save-AsarBackup {
    param([string]$Asar, [string]$Version, [string]$SourceSha)
    New-Item -ItemType Directory -Force -Path $script:BackupDir | Out-Null
    $stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
    $backup = Join-Path $script:BackupDir "app.asar.$Version.$stamp.bak"
    Copy-Item -LiteralPath $Asar -Destination $backup -Force
    Assert-Hash $backup $SourceSha 'app.asar 备份'
    Write-Ok "已备份原始 app.asar：$backup"
    return $backup
}

function Save-State {
    param($ZCode, $Info, [string]$Backup, $Manifest, [string]$VoiceDir)
    $state = [ordered]@{
        version = $Info.version
        installed_at = (Get-Date).ToString('o')
        install_dir = $ZCode.Dir
        backup = $Backup
        source_sha256 = $Manifest.source_sha256
        patched_sha256 = $Manifest.output_sha256
        voice_dir = $VoiceDir
    }
    [IO.File]::WriteAllText($script:StateFile, ($state | ConvertTo-Json), $script:Utf8NoBom)
}

function Invoke-PatchAsar {
    param([string]$SourceAsar, [string]$OutputAsar, [string]$WorkDir, [string]$ManifestPath)
    Write-Step '生成语音版 app.asar'
    $patcher = Join-Path $WorkDir 'asar-patch.mjs'
    Invoke-Node -ScriptPath $patcher -NodeArgs @(
        '--asar', $SourceAsar,
        '--out', $OutputAsar,
        '--entry', (Join-Path $WorkDir 'voice-entry.js'),
        '--ui', (Join-Path $WorkDir 'voice-ui.js'),
        '--preload-patch', (Join-Path $WorkDir 'preload-patch.cjs'),
        '--manifest', $ManifestPath
    ) | Out-Null
    if (-not (Test-Path -LiteralPath $ManifestPath)) { Fail '补丁器没有生成 manifest。' }
    $manifest = Get-Content -LiteralPath $ManifestPath -Raw | ConvertFrom-Json
    Assert-Hash $OutputAsar $manifest.output_sha256 '语音版 app.asar'
    Write-Ok '语音版 app.asar 生成并校验通过。'
    return $manifest
}

function Invoke-Uninstall {
    param($ZCode)
    $asar = if ($AsarPath) { (Resolve-Path -LiteralPath $AsarPath).Path } else { $ZCode.Asar }
    $info = Get-AsarInfo $asar
    $voiceDir = Join-Path $ZCode.Dir 'resources\voice'
    if ($info.patched) {
        $backup = $null
        if (Test-Path -LiteralPath $script:StateFile) {
            $state = Get-Content -LiteralPath $script:StateFile -Raw | ConvertFrom-Json
            if ($state.backup -and (Test-Path -LiteralPath $state.backup)) { $backup = $state.backup }
        }
        if (-not $backup) {
            $backup = Get-ChildItem -LiteralPath $script:BackupDir -Filter "app.asar.$($info.version).*.bak" -File -ErrorAction SilentlyContinue |
                Sort-Object LastWriteTime -Descending | Select-Object -First 1 -ExpandProperty FullName
        }
        if (-not $backup) { Fail '找不到原始 app.asar 备份，无法自动还原。' }
        $backupInfo = Get-AsarInfo $backup
        if ($backupInfo.patched -or $backupInfo.version -ne $info.version) { Fail '备份文件不是同版本的官方 asar，已停止还原。' }
        Write-Step '还原官方 app.asar'
        Copy-Item -LiteralPath $backup -Destination $asar -Force
        $restoredInfo = Get-AsarInfo $asar
        if ($restoredInfo.patched) { Fail '还原后 asar 仍是语音版，已停止。' }
        Write-Ok 'app.asar 已还原。'
    } else {
        Write-Ok '当前 app.asar 已是官方版本，无需还原。'
    }

    $resources = [IO.Path]::GetFullPath((Join-Path $ZCode.Dir 'resources'))
    $voiceFull = [IO.Path]::GetFullPath($voiceDir)
    if ($voiceFull.StartsWith($resources, [StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $voiceDir)) {
        Remove-Item -LiteralPath $voiceDir -Recurse -Force
        Write-Ok '已删除 resources\voice。'
    }
    if (Test-Path -LiteralPath $script:StateFile) { Remove-Item -LiteralPath $script:StateFile -Force }
    Write-Ok '卸载完成。重新启动 ZCode 即可。'
}

# ----------------------------- main -----------------------------
try {
    Initialize-Dirs
    Show-Banner
    $script:Work = Join-Path ([IO.Path]::GetTempPath()) ('ZCodeVoice-' + [guid]::NewGuid().ToString('N'))
    New-Item -ItemType Directory -Force -Path $script:Work | Out-Null
    Write-EmbeddedFiles $script:Work

    $script:ZCode = Resolve-ZCode $ZCodePath
    Assert-SupportedVersion $script:ZCode
    Write-Info "ZCode：$($script:ZCode.Dir)"
    Write-Info "版本：$($script:ZCode.Version)"

    if ($Uninstall) {
        Close-ZCodeForInstall $script:ZCode
        Invoke-Uninstall $script:ZCode
        return
    }

    if ($DryRun) { Write-Info 'Dry run：只生成并校验补丁，不修改安装。' }
    if ($AsarPath -and -not $DryRun) {
        Fail '-AsarPath 只用于 -DryRun 校验，不能用于正式安装。'
    }

    $asar = if ($AsarPath) { (Resolve-Path -LiteralPath $AsarPath).Path } else { $script:ZCode.Asar }
    $info = Get-AsarInfo $asar
    Write-Info "asar 版本：$($info.version)；已打补丁：$($info.patched)"

    if ($info.patched) {
        Write-Ok '检测到已经安装过语音补丁。'
        if ($DryRun) { return }
        $voiceDir = Join-Path $script:ZCode.Dir 'resources\voice'
        if (-not (Test-VoiceRuntime $voiceDir)) {
            Assert-FreeSpace $script:ZCode.Dir (1.5GB)
            $assets = Get-Assets $script:Cache
            Install-VoiceRuntime -VoiceDir $voiceDir -WhisperZip $assets.WhisperZip -ModelFile $assets.Model | Out-Null
        } else {
            Write-Ok '语音资源校验通过。'
        }
        Start-ZCodeApp $script:ZCode
        return
    }

    if ($info.version -ne $script:SupportedVersion) {
        Fail "asar 版本是 $($info.version)，本脚本只支持 $($script:SupportedVersion)。"
    }

    Assert-FreeSpace $script:ZCode.Dir (1.5GB)
    Assert-FreeSpace $script:Cache (1.5GB)
    $assets = Get-Assets $script:Cache

    if ($DryRun) {
        $dryDir = Join-Path $script:Root 'dryrun'
        New-Item -ItemType Directory -Force -Path $dryDir | Out-Null
        $stageVoice = Join-Path $script:Work 'voice'
        Install-VoiceRuntime -VoiceDir $stageVoice -WhisperZip $assets.WhisperZip -ModelFile $assets.Model | Out-Null
        $dryOut = Join-Path $dryDir 'app.asar.patched'
        $dryManifest = Join-Path $dryDir 'manifest.json'
        Invoke-PatchAsar -SourceAsar $asar -OutputAsar $dryOut -WorkDir $script:Work -ManifestPath $dryManifest | Out-Null
        Write-Ok "Dry run 完成：$dryOut"
        Write-Info "输出 SHA-256：$(Get-Sha256 $dryOut)"
        return
    }

    $voiceDir = Join-Path $script:ZCode.Dir 'resources\voice'
    Install-VoiceRuntime -VoiceDir $voiceDir -WhisperZip $assets.WhisperZip -ModelFile $assets.Model | Out-Null

    $patchedOut = Join-Path $script:Work 'app.asar.patched'
    $manifestPath = Join-Path $script:Work 'patch-manifest.json'
    $manifest = Invoke-PatchAsar -SourceAsar $asar -OutputAsar $patchedOut -WorkDir $script:Work -ManifestPath $manifestPath

    Close-ZCodeForInstall $script:ZCode
    $script:AsarBackup = Save-AsarBackup -Asar $asar -Version $info.version -SourceSha $manifest.source_sha256
    Write-Step '替换 app.asar'
    $script:AsarReplaced = $true
    try {
        Copy-Item -LiteralPath $patchedOut -Destination $asar -Force
        Assert-Hash $asar $manifest.output_sha256 '安装后的 app.asar'
    } catch {
        if ($script:AsarBackup -and (Test-Path -LiteralPath $script:AsarBackup)) {
            Copy-Item -LiteralPath $script:AsarBackup -Destination $asar -Force
            $script:AsarReplaced = $false
        }
        throw
    }
    Save-State -ZCode $script:ZCode -Info $info -Backup $script:AsarBackup -Manifest $manifest -VoiceDir $voiceDir
    Write-Ok 'app.asar 已替换并校验通过。'

    Start-ZCodeApp $script:ZCode
    Write-Host ''
    Write-Host '  安装完成。' -ForegroundColor Green
    Write-Host '  用法：点输入框右侧麦克风开始录音，再点一下停止；右键切换中文/自动；Esc 取消。' -ForegroundColor Gray
    Write-Host "  日志：$script:LogFile" -ForegroundColor DarkGray
    Write-Log 'install completed'
} catch {
    Write-Err $_.Exception.Message
    if ($script:AsarReplaced -and $script:AsarBackup -and (Test-Path -LiteralPath $script:AsarBackup)) {
        try {
            Copy-Item -LiteralPath $script:AsarBackup -Destination $script:ZCode.Asar -Force
            Write-Warn '已自动还原安装前的 app.asar。'
        } catch {
            Write-Warn "自动还原失败，请手动恢复备份：$script:AsarBackup"
        }
    }
    Write-Log ("install failed: " + $_.Exception.Message) 'ERROR'
    exit 1
} finally {
    if (-not $KeepWork -and $script:Work -and (Test-Path -LiteralPath $script:Work)) {
        try { Remove-Item -LiteralPath $script:Work -Recurse -Force -ErrorAction SilentlyContinue } catch {}
    }
}
